mapper.select:


    del_flag = '0'

        and (
            parent_company_china ILIKE CONCAT('%', #{searchQuery}, '%')
            or vietnam_entity_name ILIKE CONCAT('%', #{searchQuery}, '%')
            or vietnam_entity_name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or park_name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or industry ILIKE CONCAT('%', #{searchQuery}, '%')
            or tax_code ILIKE CONCAT('%', #{searchQuery}, '%')
            or stock_code ILIKE CONCAT('%', #{searchQuery}, '%')
        )


        and park_id = #{parkId}


        and province_vietnam = #{provinceVietnam}


        and parent_province_china = #{parentProvinceChina}


        and industry = #{industry}


        and stock_listing_status = #{stockListingStatus}


        and investment_mode = #{investmentMode}


        and status = #{status}


order by create_time desc nulls last, vietnam_entity_name_cn asc
